// Collection pre-request: establish a unique run id, a timestamp, and attach the
// current bearer token only when one is present (never send an empty Authorization).
const runId = pm.environment.get('runId') || (Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8));
pm.environment.set('runId', runId);
pm.environment.set('timestamp', new Date().toISOString());

const token = pm.environment.get('accessToken');
if (token && String(token).length > 0) {
    pm.request.headers.upsert({ key: 'Authorization', value: 'Bearer ' + token });
} else {
    pm.request.headers.remove('Authorization');
}

if (pm.request.method !== 'GET' && pm.request.method !== 'DELETE') {
    pm.request.headers.upsert({ key: 'Content-Type', value: '{{contentType}}' });
}

// Collection-level smoke assertion: no endpoint should return a 500 for valid test data.
// (503 is allowed: /health/ready returns it when a database is unreachable.)
pm.test('No unexpected server error (status != 500)', function () {
    pm.expect(pm.response.code).to.not.eql(500);
});

// 204 No Content (and a bare 503) have no body; only assert JSON when a Content-Type is present.
const ct = pm.response.headers.get('Content-Type') || '';
if (ct.length > 0) {
    pm.test('Response is JSON', function () {
        pm.expect(ct).to.include('application/json');
    });
}

pm.test('200 OK', () => pm.response.to.have.status(200));
const b = pm.response.json();
pm.test('access token present', () => pm.expect(b.accessToken).to.be.a('string').and.not.empty);
pm.test('refresh token present', () => pm.expect(b.refreshToken).to.be.a('string').and.not.empty);
pm.test('user id present', () => pm.expect(b.user.id).to.be.a('string'));
pm.environment.set('accessToken', b.accessToken);
pm.environment.set('refreshToken', b.refreshToken);
pm.environment.set('accessTokenExpiresAt', b.accessTokenExpiresAt);
pm.environment.set('adminUserId', b.user.id);

pm.test('200 OK', () => pm.response.to.have.status(200));
const b = pm.response.json();
pm.test('new access token present', () => pm.expect(b.accessToken).to.be.a('string').and.not.empty);
pm.test('new refresh token differs from old', () => pm.expect(b.refreshToken).to.not.eql(pm.environment.get('refreshToken')));
pm.environment.set('refreshTokenOld', pm.environment.get('refreshToken'));
pm.environment.set('refreshTokenNew', b.refreshToken);
pm.environment.set('accessToken', b.accessToken);
pm.environment.set('refreshToken', b.refreshToken);

pm.test('200 OK', () => pm.response.to.have.status(200));
const b = pm.response.json();
pm.test('paged result has items/totalCount', () => { pm.expect(b).to.have.property('items'); pm.expect(b).to.have.property('totalCount'); });

pm.test('201 Created', () => pm.response.to.have.status(201));
const b = pm.response.json();
pm.test('id present', () => pm.expect(b.id).to.be.a('string'));
pm.test('email immutable input echoed', () => pm.expect(b.email).to.eql('user-' + pm.environment.get('runId') + '@example.com'));
pm.environment.set('createdUserId', b.id);
pm.environment.set('testUserId', b.id);

pm.test('201 Created', () => pm.response.to.have.status(201));
const b = pm.response.json();
pm.environment.set('createdRoleId', b.id);
pm.environment.set('roleId', b.id);
pm.environment.set('roleConcurrencyStamp', b.concurrencyStamp);
